	JAE     rp_shim
	MOVQ    FN_STRUCT_LAYOUT_TABLE(AX), SI
	SHLQ    $4, BX
	ADDQ    BX, SI
	MOVQ    DX, AX
	SHRQ    $16, AX
	MOVBLZX AL, AX
	MOVQ    CTX_GENERALS_BASE(R15), DI
	LEAQ    (AX)(AX*2), CX
	LEAQ    (DI)(CX*8), DI
	MOVQ    0(DI), CX
	TESTQ   CX, CX
	JZ      rp_zero
	MOVQ    16(DI), CX
	MOVQ    CX, BX
	ANDQ    $0x1F, BX
	CMPQ    BX, $22
	JE      rp_ptr_recv
	CMPQ    BX, $25
	JNE     rp_shim
	TESTQ   $0x100, CX
	JZ      rp_shim
	MOVQ    8(DI), DI
	JMP     rp_have_base
rp_ptr_recv:
	MOVQ    8(DI), DI
	TESTQ   $0x80, CX
	JZ      rp_have_base
	MOVQ    (DI), DI
rp_have_base:
	TESTQ   DI, DI
	JZ      rp_zero
	MOVLQZX OFF_LAYOUT_OFFSET(SI), CX
	ADDQ    CX, DI
	MOVQ    (DI), CX
	MOVQ    8(DI), SI
	MOVQ    DX, AX
	SHRQ    $8, AX
	MOVBLZX AL, AX
	MOVQ    CTX_GENERALS_BASE(R15), DI
	LEAQ    (AX)(AX*2), BX
	LEAQ    (DI)(BX*8), DI
	TESTQ   CX, CX
	JZ      rp_store_zero
	MOVQ    CX, 0(DI)
	MOVQ    SI, 8(DI)
	MOVQ    $22, 16(DI)
	JMP     rp_done
rp_zero:
