rp_shim:
	JMP     ·handlerPathBShimGetStructFieldRawPointer(SB)

// handlerEqualGeneral sets ints[A] = (general[B] == general[C]) for invalid pairs, differing type words, and pointer-identity kinds. Other shapes fall back to handlerPathBShimEqualGeneral.
TEXT ·handlerEqualGeneral(SB), NOSPLIT|NOFRAME, $0
	MOVQ    DX, BX
	SHRQ    $16, BX
	MOVBLZX BL, BX
	MOVQ    DX, CX
	SHRQ    $24, CX
	MOVQ    CTX_GENERALS_BASE(R15), DI
	LEAQ    (BX)(BX*2), AX
	LEAQ    (DI)(AX*8), SI
	LEAQ    (CX)(CX*2), AX
	LEAQ    (DI)(AX*8), DI
	MOVQ    0(SI), AX
	MOVQ    0(DI), CX
	TESTQ   AX, AX
	JZ      eqg_a_invalid
	TESTQ   CX, CX
	JZ      eqg_shim
	MOVQ    16(SI), BX
	ANDQ    $0x1F, BX
	CMPQ    BX, $20
	JE      eqg_shim
	MOVQ    16(DI), CX
	ANDQ    $0x1F, CX
	CMPQ    CX, $20
	JE      eqg_shim
	CMPQ    AX, 0(DI)
	JNE     eqg_store_zero
	CMPQ    BX, $18
	JE      eqg_ptr_cmp
	CMPQ    BX, $22
	JE      eqg_ptr_cmp
	CMPQ    BX, $26
	JNE     eqg_shim
eqg_ptr_cmp:
	MOVQ    16(SI), CX
	MOVQ    8(SI), AX
	TESTQ   $0x80, CX
