	MOVQ    (AX), AX
eqg_a_direct:
	MOVQ    16(DI), CX
	MOVQ    8(DI), BX
	TESTQ   $0x80, CX
	JZ      eqg_b_direct
	MOVQ    (BX), BX
eqg_b_direct:
	XORQ    CX, CX
	CMPQ    AX, BX
	JNE     eqg_store
	MOVQ    $1, CX
	JMP     eqg_store
eqg_a_invalid:
	TESTQ   CX, CX
	JNE     eqg_shim
	MOVQ    $1, CX
	JMP     eqg_store
eqg_store_zero:
	XORQ    CX, CX
eqg_store:
	MOVQ    DX, AX
	SHRQ    $8, AX
	MOVBLZX AL, AX
	MOVQ    CX, (R8)(AX*8)
	DISPATCH_NEXT()
