	SHRQ    $8, AX
	MOVBLZX AL, AX
	MOVQ    CTX_GENERALS_BASE(R15), DI
	LEAQ    (AX)(AX*2), CX
	LEAQ    (DI)(CX*8), DI
	MOVQ    0(DI), CX
	TESTQ   CX, CX
	JZ      tnj_take
	MOVQ    16(DI), CX
	MOVQ    CX, BX
	ANDQ    $0x1F, BX
	CMPQ    BX, $18
	JB      tnj_skip
	CMPQ    BX, $23
	JA      tnj_skip
	TESTQ   $0x200, CX
	JNZ     tnj_skip
	MOVQ    8(DI), SI
	CMPQ    BX, $20
	JE      tnj_deref
	CMPQ    BX, $23
	JE      tnj_deref
	TESTQ   $0x80, CX
	JZ      tnj_word
tnj_deref:
	MOVQ    (SI), SI
tnj_word:
	TESTQ   SI, SI
	JZ      tnj_take
	JMP     tnj_skip
tnj_take:
	SHRQ    $16, DX
	MOVWLZX DX, AX
	MOVWQSX AX, AX
	ADDQ    AX, R14
	DECQ    CTX_POLL_BUDGET(R15)
	JG      tnj_skip
	MOVQ    R14, CTX_PC(R15)
	MOVQ    $EXIT_POLL, CTX_EXIT_REASON(R15)
	MOVQ    R14, CTX_EXIT_PC(R15)
	RET     
tnj_skip:
	DISPATCH_NEXT()

